```python
import random
import numpy as np
from collections import deque

# Set the seed for reproducibility
np.random.seed(seed)

# Function to create a graph
def create_graph(num_nodes, connection_prob=0.5):
    graph = {}
    for i in range(num_nodes):
        graph[i] = set()
    for i in range(num_nodes):
        for j in range(num_nodes):
            if i != j and random.random() < connection_prob:
                graph[i].add(j)
    return graph

# Function to perform BFS and find a path
def bfs_search(graph, start, goal):
    visited = set()
    queue = deque([(start, [start])])  # (node, path)

    while queue:
        (node, path) = queue.popleft()
        if node not in visited:
            visited.add(node)
            if node == goal:
                return path
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))
    return None

# Create a graph with 5 nodes
num_nodes = 5
graph = create_graph(num_nodes)

# Define start and goal nodes
start_node = 0
goal_node = 4

# Perform BFS to find a path
path = bfs_search(graph, start_node, goal_node)

# Print the result
if path:
    print(f"A path from {start_node} to {goal_node} is: {path}")
else:
    print(f"No path found from {start_node} to {goal_node}")
```

