```python
import random

class Graph:
    def __init__(self):
        self.graph = {}

    def add_edge(self, u, v):
        if u in self.graph:
            self.graph[u].append(v)
        else:
            self.graph[u] = [v]

    def dfs(self, start, target, path=None):
        if path is None:
            path = []
        path = path + [start]

        if start == target:
            return path

        for node in self.graph.get(start, []):
            if node not in path:
                new_path = self.dfs(node, target, path)
                if new_path:
                    return new_path

        return None

def generate_random_graph(n_nodes, n_edges, seed):
    random.seed(seed)
    g = Graph()
    for i in range(n_nodes):
        for j in range(n_nodes):
            if i != j and random.random() < 0.5:
                g.add_edge(i, j)
    return g

def main():
    seed = "7rdkda4w0xz"
    random.seed(seed)

    # Generate a random graph
    g = generate_random_graph(10, 15, seed)

    # Define the start and target nodes
    start_node = 0
    target_node = 9

    # Run DFS to find a path
    path = g.dfs(start_node, target_node)
    if path:
        print(f"Path found from {start_node} to {target_node}: {path}")
    else:
        print(f"No path found from {start_node} to {target_node}")

if __name__ == "__main__":
    main()
```

