Now, let's implement a DFS algorithm to find a path from a starting node to an ending node. If you don't have a specific starting and ending node, we'll assume we want to find a path from node 'A' to node 'F'.

Here's the Python code:

```python
import random

class Node:
    def __init__(self, name):
        self.name = name

class Graph:
    def __init__(self, graph_dict=None):
        if graph_dict is None:
            graph_dict = {}
        self.graph_dict = graph_dict

    def add_node(self, node):
        if node.name not in self.graph_dict:
            self.graph_dict[node.name] = []

    def add_edge(self, node1, node2):
        if node1 in self.graph_dict and node2 in self.graph_dict:
            self.graph_dict[node1].append(node2)
            self.graph_dict[node2].append(node1)

    def dfs(self, start, end):
        stack = [(start, [start])]
        while stack:
            (vertex, path) = stack.pop()
            for next_vertex in self.graph_dict[vertex]:
                if next_vertex not in path:  # Avoid cycles
                    if next_vertex == end:
                        yield path + [next_vertex]
                    else:
                        stack.append((next_vertex, path + [next_vertex]))

def generate_random_graph(size=10, p=0.3):
    graph = {}
    nodes = [Node(str(i)) for i in range(size)]
    for i, node1 in enumerate(nodes):
        for node2 in nodes[i+1:]:
            if random.random() < p:
                graph[node1.name] = graph.get(node1.name, []) + [node2.name]
                graph[node2.name] = graph.get(node2.name, []) + [node1.name]
    return Graph(graph)

def main():
    seed = 24esihktvh3  # This should be an integer
    random.seed(seed)
    graph = generate_random_graph()
    for node in graph.graph_dict.keys():
        graph.add_node(Node(node))
    for node1, nodes in graph.graph_dict.items():
        for node2 in nodes:
            graph.add_edge(node1, node2)

    start_node = 'A'
    end_node = 'F'
    print(f"Starting DFS from {start_node} to {end_node}...")
    for path in graph.dfs(start_node, end_node):
        print(f"Path found: {' -> '.join(path)}")

if __name__ == "__main__":
    main()
```

### Explanation:
1. **Node and Graph Classes**: 
    - `Node` is a simple class to represent a node.
    - `Graph` has methods to add nodes and edges to the graph.

2. **Depth-First Search (DFS)**:
    - The `dfs` method performs a DFS traversal starting from the `start` node and yields paths leading from the `start` node to the `end` node.

3. **Generating a Random Graph**:
    - `generate_random_graph` creates a random graph with a given number of nodes and a probability `p` for adding an edge between two nodes.

4. **Main Execution**:
    - The `main` function initializes the graph, performs DFS, and prints the paths.

