                if visited[neighbour] == False:
                    self.print_all_paths_util(neighbour, end, visited, path)
        path.pop()
        visited[start] = False

    def print_all_paths(self, start, end):
        visited = {node: False for node in self.graph_dict}
        path = []
        self.print_all_paths_util(start, end, visited, path)

