graph_dict = {
    "A": {"B": 1, "C": 3, "D": 7},
    "B": {"A": 1, "D": 2},
    "C": {"A": 3, "D": 4},
    "D": {"A": 7, "B": 2, "C": 4}
}

g = Graph(graph_dict, directed=False)
path = bfs_search(g, "A", "D")
print(f"Path: {path}")
```

