def relax(graph, distance, u, v):
    """Relaxation step of Dijkstra's algorithm."""
    if distance[u] + graph[u][v] < distance[v]:
        distance[v] = distance[u] + graph[u][v]
        return True
    return False

def dijkstra(graph, src):
    """Dijkstra's algorithm to find shortest paths from a source vertex."""
    n = len(graph)
    distance = {vertex: float('inf') for vertex in graph}
    distance[src] = 0
    processed = set()

    pq = [(0, src)]  # Priority queue with (distance, vertex)

    while pq:
        dist, u = heapq.heappop(pq)
        if u in processed:
            continue
        processed.add(u)

        for v in graph[u]:
            if relax(graph, distance, u, v):
                heapq.heappush(pq, (distance[v], v))

    return distance

